style:
.airplane-dashboard {
    padding: 20px;
    border-radius: 10px;
    background: #f8f9fa;
    border: 1px solid #e5e7eb;
}

.airplane-header {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 18px;
    border-radius: 10px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
}

.airplane-icon {
    font-size: 32px;
}

.airplane-header h2 {
    margin: 0 0 5px;
    font-size: 24px;
}

.airplane-header p {
    margin: 0;
    color: #6b7280;
}

.airplane-intro {
    margin-top: 16px;
}

.airplane-intro h3 {
    margin-bottom: 5px;
}

.airplane-intro p {
    margin: 0;
    color: #6b7280;
}

.airplane-items {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-top: 18px;
}

.airplane-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 14px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    cursor: pointer;
    transition: background 0.15s ease, box-shadow 0.15s ease;
}

.airplane-item:hover {
    background: #f9fafb;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
}

.airplane-item span {
    font-size: 20px;
}

.airplane-item strong {
    font-size: 14px;
}
